   140→    <body>
   141→      <div class="header">
   142→        <h1><%= @transaction.title %></h1>
   143→        <span class="transaction-type"><%= t("enums.transaction_type.#{@transaction.transaction_type}") %></span>
   144→      </div>
   145→
   146→      <div class="header-details">
   147→        <div class="detail-row">
   148→          <span class="detail-label">Tanggal:</span>
   149→          <span class="detail-value"><%= l(@transaction.date, format: :long) %></span>
   150→        </div>
   151→
   152→        <div class="detail-row">
   153→          <span class="detail-label">Status:</span>
