   157→        <div class="detail-row">
   158→          <span class="detail-label">Sumber Input:</span>
   159→          <span class="detail-value"><%= t("enums.source_type.#{@transaction.source_type}") %></span>
   160→        </div>
   161→
   162→        <!-- Metadata fields (except custom fields) in header -->
