   178→                </div>
   179→              <% end %>
   180→              <% if metadata_for_type['notes'].present? %>
   181→                <div class="detail-row">
   182→                  <span class="detail-label">Catatan:</span>
   183→                  <span class="detail-value"><%= metadata_for_type['notes'] %></span>
   184→                </div>
   185→              <% end %>
   186→            <% when 'invoice' %>
