   195→                  <span class="detail-label">Nama Klien:</span>
   196→                  <span class="detail-value"><%= metadata_for_type['client_name'] %></span>
   197→                </div>
   198→              <% end %>
   199→              <% if metadata_for_type['due_date'].present? %>
   200→                <div class="detail-row">
   201→                  <span class="detail-label">Tanggal Jatuh Tempo:</span>
   202→                  <span class="detail-value"><%= metadata_for_type['due_date'] %></span>
   203→                </div>
   204→              <% end %>
   205→              <% if metadata_for_type['tax_rate'].present? %>
