   273→                </div>
   274→              <% end %>
   275→              <% if metadata_for_type['interest_rate'].present? %>
   276→                <div class="detail-row">
   277→                  <span class="detail-label">Suku Bunga:</span>
   278→                  <span class="detail-value"><%= metadata_for_type['interest_rate'] %>%</span>
   279→                </div>
   280→              <% end %>
   281→              <% if metadata_for_type['payment_due_date'].present? %>
   282→                <div class="detail-row">
   283→                  <span class="detail-label">Tanggal Jatuh Tempo Pembayaran:</span>
   284→                  <span class="detail-value"><%= metadata_for_type['payment_due_date'] %></span>
   285→                </div>
   286→              <% end %>
   287→              <% if metadata_for_type['debt_type'].present? %>
   288→                <div class="detail-row">
   289→                  <span class="detail-label">Jenis Hutang:</span>
   290→                  <span class="detail-value"><%= metadata_for_type['debt_type'] %></span>
   291→                </div>
   292→              <% end %>
   293→            <% when 'regular_payment' %>
   294→              <% if metadata_for_type['frequency'].present? %>
   295→                <div class="detail-row">
   296→                  <span class="detail-label">Frekuensi:</span>
   297→                  <span class="detail-value"><%= metadata_for_type['frequency'] %></span>
   298→                </div>
   299→              <% end %>
   300→              <% if metadata_for_type['start_date'].present? %>
   301→                <div class="detail-row">
   302→                  <span class="detail-label">Tanggal Mulai:</span>
   303→                  <span class="detail-value"><%= metadata_for_type['start_date'] %></span>
   304→                </div>
   305→              <% end %>
   306→              <% if metadata_for_type['end_date'].present? %>
   307→                <div class="detail-row">
   308→                  <span class="detail-label">Tanggal Berakhir:</span>
   309→                  <span class="detail-value"><%= metadata_for_type['end_date'] %></span>
   310→                </div>
   311→              <% end %>
   312→              <% if metadata_for_type['purpose'].present? %>
   313→                <div class="detail-row">
   314→                  <span class="detail-label">Tujuan:</span>
   315→                  <span class="detail-value"><%= metadata_for_type['purpose'] %></span>
   316→                </div>
   317→              <% end %>
   318→              <% if metadata_for_type['notes'].present? %>
   319→                <div class="detail-row">
   320→                  <span class="detail-label">Catatan:</span>
   321→                  <span class="detail-value"><%= metadata_for_type['notes'] %></span>
   322→                </div>
   323→              <% end %>
   324→            <% when 'cashflow' %>
   325→              <% if metadata_for_type['category'].present? %>
   326→                <div class="detail-row">
   327→                  <span class="detail-label">Kategori:</span>
   328→                  <span class="detail-value"><%= metadata_for_type['category'] %></span>
   329→                </div>
   330→              <% end %>
   331→              <% if metadata_for_type['account'].present? %>
   332→                <div class="detail-row">
   333→                  <span class="detail-label">Akun:</span>
   334→                  <span class="detail-value"><%= metadata_for_type['account'] %></span>
   335→                </div>
   336→              <% end %>
   337→              <% if metadata_for_type['reference_number'].present? %>
   338→                <div class="detail-row">
   339→                  <span class="detail-label">Nomor Referensi:</span>
   340→                  <span class="detail-value"><%= metadata_for_type['reference_number'] %></span>
   341→                </div>
   342→              <% end %>
   343→              <% if metadata_for_type['notes'].present? %>
   344→                <div class="detail-row">
   345→                  <span class="detail-label">Catatan:</span>
   346→                  <span class="detail-value"><%= metadata_for_type['notes'] %></span>
   347→                </div>
   348→              <% end %>
   349→            <% when 'purchase_order' %>
   350→              <% if metadata_for_type['po_number'].present? %>
   351→                <div class="detail-row">
   352→                  <span class="detail-label">Nomor PO:</span>
   353→                  <span class="detail-value"><%= metadata_for_type['po_number'] %></span>
   354→                </div>
   355→              <% end %>
   356→              <% if metadata_for_type['supplier_name'].present? %>
   357→                <div class="detail-row">
   358→                  <span class="detail-label">Nama Supplier:</span>
   359→                  <span class="detail-value"><%= metadata_for_type['supplier_name'] %></span>
   360→                </div>
   361→              <% end %>
   362→              <% if metadata_for_type['delivery_date'].present? %>
   363→                <div class="detail-row">
   364→                  <span class="detail-label">Tanggal Pengiriman:</span>
   365→                  <span class="detail-value"><%= metadata_for_type['delivery_date'] %></span>
   366→                </div>
   367→              <% end %>
   368→              <% if metadata_for_type['payment_terms'].present? %>
   369→                <div class="detail-row">
   370→                  <span class="detail-label">Syarat Pembayaran:</span>
   371→                  <span class="detail-value"><%= metadata_for_type['payment_terms'] %></span>
   372→                </div>
   373→              <% end %>
   374→              <% if metadata_for_type['department'].present? %>
   375→                <div class="detail-row">
   376→                  <span class="detail-label">Departemen:</span>
   377→                  <span class="detail-value"><%= metadata_for_type['department'] %></span>
   378→                </div>
   379→              <% end %>
   380→              <% if metadata_for_type['approval_status'].present? %>
   381→                <div class="detail-row">
   382→                  <span class="detail-label">Status Persetujuan:</span>
   383→                  <span class="detail-value"><%= t("transactions.approval_status.#{metadata_for_type['approval_status']}") rescue metadata_for_type['approval_status'] %></span>
   384→                </div>
   385→              <% end %>
   386→              <% if metadata_for_type['notes'].present? %>
   387→                <div class="detail-row">
   388→                  <span class="detail-label">Catatan:</span>
   389→                  <span class="detail-value"><%= metadata_for_type['notes'] %></span>
   390→                </div>
   391→              <% end %>
   392→            <% end %>
   393→          <% end %>
   394→        <% end %>
   395→      </div>
   396→
   397→      <div class="line-items-section">
   398→        <h3>Daftar Item</h3>
   399→          
   400→          <table style="width: 100%; border-collapse: collapse; margin-top: 15px;">
   401→            <thead>
   402→              <tr style="background-color: #f3f4f6;">
   403→                <th style="border: 1px solid #d1d5db; padding: 12px; text-align: left; font-weight: bold; color: #374151;">No.</th>
   404→                <th style="border: 1px solid #d1d5db; padding: 12px; text-align: left; font-weight: bold; color: #374151;">Nama Item</th>
   405→                <th style="border: 1px solid #d1d5db; padding: 12px; text-align: left; font-weight: bold; color: #374151;">Deskripsi</th>
   406→                <th style="border: 1px solid #d1d5db; padding: 12px; text-align: center; font-weight: bold; color: #374151;">Qty</th>
   407→                <th style="border: 1px solid #d1d5db; padding: 12px; text-align: right; font-weight: bold; color: #374151;">Harga Satuan</th>
   408→                <th style="border: 1px solid #d1d5db; padding: 12px; text-align: right; font-weight: bold; color: #374151;">Total</th>
   409→              </tr>
   410→            </thead>
   411→            <tbody>
   412→              <!-- Parent transaction as first row -->
   413→              <tr style="background-color: #e5e7eb; font-weight: bold;">
   414→                <td style="border: 1px solid #d1d5db; padding: 8px; text-align: center;">1</td>
   415→                <td style="border: 1px solid #d1d5db; padding: 8px; font-weight: bold;"><%= @transaction.title %></td>
   416→                <td style="border: 1px solid #d1d5db; padding: 8px; color: #6b7280;"><%= @transaction.description.present? ? @transaction.description : "-" %></td>
   417→                <td style="border: 1px solid #d1d5db; padding: 8px; text-align: center;"><%= @transaction.quantity || 1 %></td>
   418→                <td style="border: 1px solid #d1d5db; padding: 8px; text-align: right;">
   419→                  <%= number_to_currency(@transaction.amount, unit: @transaction.currency + " ", separator: ",", delimiter: ".") %>
   420→                </td>
   421→                <td style="border: 1px solid #d1d5db; padding: 8px; text-align: right; font-weight: bold;">
   422→                  <%= number_to_currency(@transaction.amount * (@transaction.quantity || 1), unit: @transaction.currency + " ", separator: ",", delimiter: ".") %>
   423→                </td>
   424→              </tr>
   425→              
   426→              <!-- Children transactions -->
   427→              <% @transaction.children.each_with_index do |child, index| %>
   428→                <tr style="<%= (index + 1) % 2 == 0 ? 'background-color: #f9fafb;' : '' %>">
   429→                  <td style="border: 1px solid #d1d5db; padding: 8px; text-align: center;"><%= index + 2 %></td>
   430→                  <td style="border: 1px solid #d1d5db; padding: 8px; font-weight: bold;"><%= child.title %></td>
   431→                  <td style="border: 1px solid #d1d5db; padding: 8px; color: #6b7280;"><%= child.description.present? ? child.description : "-" %></td>
   432→                  <td style="border: 1px solid #d1d5db; padding: 8px; text-align: center;"><%= child.quantity || 1 %></td>
   433→                  <td style="border: 1px solid #d1d5db; padding: 8px; text-align: right;">
   434→                    <%= number_to_currency(child.amount, unit: child.currency + " ", separator: ",", delimiter: ".") %>
   435→                  </td>
   436→                  <td style="border: 1px solid #d1d5db; padding: 8px; text-align: right; font-weight: bold;">
   437→                    <%= number_to_currency(child.amount * (child.quantity || 1), unit: child.currency + " ", separator: ",", delimiter: ".") %>
   438→                  </td>
   439→                </tr>
   440→              <% end %>
   441→            </tbody>
   442→            <tfoot>
   443→              <tr style="background-color: #374151; color: white; font-weight: bold;">
   444→                <td colspan="5" style="border: 1px solid #374151; padding: 12px; text-align: right;">TOTAL KESELURUHAN:</td>
   445→                <td style="border: 1px solid #374151; padding: 12px; text-align: right; font-size: 16px;">
   446→                  <%= number_to_currency(@transaction.total_with_children, unit: @transaction.currency + " ", separator: ",", delimiter: ".") %>
   447→                </td>
   448→              </tr>
   449→            </tfoot>
   450→          </table>
   451→        </div>
   452→
   453→      <!-- Custom Fields Section at Bottom -->
   454→      <% if @transaction.metadata.present? %>
   455→        <% metadata_for_type = @transaction.metadata[@transaction.transaction_type.to_s] %>
   456→        <% if metadata_for_type.present? && metadata_for_type['custom_fields'].present? && metadata_for_type['custom_fields'].any? %>
   457→          <div class="custom-fields-section" style="margin-top: 30px;">
   458→            <h3>Informasi Tambahan</h3>
   459→            <div class="custom-fields">
   460→              <% custom_fields = metadata_for_type['custom_fields'] %>
   461→              <% if custom_fields.is_a?(Hash) %>
   462→                <% custom_fields.values.each do |field| %>
   463→                  <% if field.is_a?(Hash) && field['label'].present? && field['value'].present? %>
   464→                    <div class="custom-field">
   465→                      <div class="custom-field-label"><%= field['label'] %></div>
   466→                      <div class="custom-field-value"><%= field['value'] %></div>
   467→                    </div>
   468→                  <% end %>
   469→                <% end %>
   470→              <% elsif custom_fields.is_a?(Array) %>
   471→                <% custom_fields.each do |field| %>
   472→                  <% if field.is_a?(Hash) && field['label'].present? && field['value'].present? %>
   473→                    <div class="custom-field">
   474→                      <div class="custom-field-label"><%= field['label'] %></div>
   475→                      <div class="custom-field-value"><%= field['value'] %></div>
   476→                    </div>
   477→                  <% end %>
   478→                <% end %>
   479→              <% end %>
   480→            </div>
   481→          </div>
   482→        <% end %>
   483→      <% end %>
   484→
   485→      <div class="footer">
   486→        <p>Dokumen ini dibuat secara otomatis pada <%= l(Time.current, format: :long) %></p>
   487→      </div>
   488→    </body>
   489→  </html>
   490→<% end %>
