import { Controller } from "@hotwired/stimulus"

// Connects to data-controller="dynamic-fields"
export default class extends Controller {
  static targets = ["container", "template"]
  static values = { 
    fieldName: String,
    maxFields: { type: Number, default: 10 }
  }

  connect() {
    this.index = this.containerTarget.children.length
  }

  add(event) {
    event.preventDefault()

    if (this.index >= this.maxFieldsValue) {
      alert(`Maximum ${this.maxFieldsValue} fields allowed`)
      return
    }

    const template = this.templateTarget.innerHTML
    const newField = template
      .replace(/TEMPLATE_INDEX/g, this.index)
      .replace(/TEMPLATE_FIELD_NAME/g, this.fieldNameValue)

    this.containerTarget.insertAdjacentHTML('beforeend', newField)
    this.index++

    // Focus on the first input of the new field
    const newFieldElement = this.containerTarget.lastElementChild
    const firstInput = newFieldElement.querySelector('input[type="text"]')
    if (firstInput) {
      firstInput.focus()
    }

    this.updateRemoveButtons()
  }

  remove(event) {
    event.preventDefault()
    const fieldGroup = event.target.closest('[data-field-group]')
    if (fieldGroup) {
      fieldGroup.remove()
      this.updateIndices()
      this.updateRemoveButtons()
    }
  }

  updateIndices() {
    const fieldGroups = this.containerTarget.querySelectorAll('[data-field-group]')
    fieldGroups.forEach((group, index) => {
      const inputs = group.querySelectorAll('input, select, textarea')
      inputs.forEach(input => {
        const name = input.getAttribute('name')
        if (name) {
          const newName = name.replace(/\[\d+\]/, `[${index}]`)
          input.setAttribute('name', newName)
        }

        const id = input.getAttribute('id')
        if (id) {
          const newId = id.replace(/_\d+_/, `_${index}_`)
          input.setAttribute('id', newId)
        }
      })

      const labels = group.querySelectorAll('label')
      labels.forEach(label => {
        const htmlFor = label.getAttribute('for')
        if (htmlFor) {
          const newFor = htmlFor.replace(/_\d+_/, `_${index}_`)
          label.setAttribute('for', newFor)
        }
      })
    })

    this.index = fieldGroups.length
  }

  updateRemoveButtons() {
    const removeButtons = this.containerTarget.querySelectorAll('[data-action*="dynamic-fields#remove"]')
    const shouldShow = removeButtons.length > 1

    removeButtons.forEach(button => {
      button.style.display = shouldShow ? 'flex' : 'none'
    })
  }
}

